head.b:skin:
/* =========================================================
   SaeBerita v2.1  -  warna & ukuran utama (ubah di sini)
   ========================================================= */
:root{
  --red:#d01e27;        /* merah menu & aksen */
  --red-d:#b3121b;      /* merah teks kecil */
  --navy:#072569;       /* navy judul */
  --navy-2:#0e3a8c;
  --ink:#232323;
  --muted:#5f5f5f;
  --line:#e5e5e5;
  --soft:#f5f6f8;
  --sec:#e9ecef;        /* bar menu kedua */
  --foot:#e3e3e3;       /* footer */
  --pill:#ffe5e5;       /* latar pill kategori */
  --gold:#ffc72c;
  --wrap:1080px;
  --side:320px;
  --gap:24px;
  --r:8px;
  --fh:'Lato',Arial,sans-serif;
  --fb:'Open Sans',Arial,sans-serif;
  --stick:136px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:var(--fb);color:var(--ink);background:#fff;font-size:15px;line-height:1.55;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img{max-width:100%;height:auto;display:block}
ul,ol{list-style:none}
button{font:inherit;cursor:pointer;border:0;background:none;color:inherit}
h1,h2,h3,h4{font-family:var(--fh);font-weight:700;overflow-wrap:break-word}
.wrap{max-width:calc(var(--wrap) + 32px);margin:0 auto;padding:0 16px}
.widget{margin:0}
.widget h2.title,.widget>h3.title{display:none}
.lbl{display:none}
.home-only{display:none}
.is-home .home-only{display:block}
.vh{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.nil{display:none!important}

/* ---------- Iklan ---------- */
.ad-box{display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;max-width:100%}
.ad-lbl{font-size:10px;color:#6f6f6f;text-transform:uppercase;letter-spacing:.04em;text-align:center;padding:5px 0}
.ad-ph{display:flex;align-items:center;justify-content:center;background:repeating-linear-gradient(45deg,#ececec 0 10px,#e3e3e3 10px 20px);color:#8a8a8a;font:600 11px/1.2 var(--fb);letter-spacing:.05em;text-transform:uppercase;max-width:100%;text-align:center}
.ph-970x250{width:970px;height:250px}.ph-970x90{width:970px;height:90px}.ph-728x90{width:728px;height:90px}
.ph-300x250{width:300px;height:250px}.ph-300x600{width:300px;height:600px}.ph-160x600{width:160px;height:600px}
.ph-320x50{width:320px;height:50px}.ph-336x280{width:336px;height:280px}
.top-ad{background:#f2f2f2;padding:0 0 12px}
.bill{background:#f2f2f2;padding:0 0 14px;border-radius:2px}
.bill-w{margin-top:18px}
.ad-inj{margin:6px 0 26px;background:#f6f6f6;padding:0 0 12px;border-radius:4px}
.side-ad{background:#f2f2f2;padding:0 0 12px;border-radius:2px}

/* ---------- Header ---------- */
.site-header{background:#fff}
.hd{display:flex;align-items:center;gap:24px;height:74px}
.logo{flex:none;display:flex;align-items:center}
.logo img{max-height:44px;width:auto}
.logo-text{display:inline-flex;align-items:stretch;font:900 25px/1 var(--fh);letter-spacing:.01em;border:2px solid var(--red);border-radius:3px;overflow:hidden;text-transform:uppercase;white-space:nowrap}
.logo-text b{background:var(--red);color:#fff;padding:6px 7px 5px;font-weight:900}
.logo-text i{font-style:normal;color:var(--navy);padding:6px 7px 5px;background:#fff}
.hd-search{flex:1;max-width:470px;display:flex;align-items:center;height:40px;border:1px solid #cfcfcf;border-radius:999px;padding:0 4px 0 18px}
.hd-search input{flex:1;min-width:0;border:0;outline:0;font:inherit;font-size:14px;background:none;color:var(--ink)}
.hd-search button{width:30px;height:30px;border-radius:50%;background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;flex:none}
.hd-icons{margin-left:auto;display:flex;align-items:stretch;height:74px}
.hd-ico{display:flex;align-items:center;justify-content:center;padding:0 20px;border-left:1px solid var(--line);gap:8px;font:900 16px var(--fh);color:var(--navy);letter-spacing:.02em}
.hd-ico:hover{background:#fafafa}
.ic-c{width:38px;height:38px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex:none}
.ic-net{background:var(--red);color:#fff;font:900 20px var(--fh)}
.ic-live{background:var(--red);color:#fff;font:800 9px var(--fb);box-shadow:inset 0 0 0 3px #fff;border:1px solid var(--red)}
.ic-user{background:var(--navy);color:#fff}
.hd-btn{display:none;width:40px;height:40px;align-items:center;justify-content:center;color:var(--navy)}

/* ---------- Menu utama (merah) + mega menu (navy) ---------- */
.stick{position:sticky;top:0;z-index:90;background:#fff}
.main-nav{background:linear-gradient(90deg,var(--navy) 50%,var(--red) 50%);position:relative}
.main-nav>.wrap{background:var(--red)}
.nav-list{display:flex;align-items:stretch;justify-content:space-between;height:40px}
.nav-list>li{position:static}
.nav-list>li>a{display:flex;align-items:center;height:40px;padding:0 13px;color:#fff;font:700 14.4px var(--fb);white-space:nowrap}
.nav-list>li.home>a{color:var(--gold);padding:0 16px}
.nav-list>li>a:hover,.nav-list>li.on>a,.nav-list>li:hover>a{color:var(--gold)}
.mega,.drop{position:absolute;top:100%;opacity:0;visibility:hidden;transform:translateY(6px);transition:.16s ease;z-index:95}
.mega{left:0;right:0;background:var(--navy);box-shadow:0 18px 30px rgba(0,0,0,.25)}
.mega .wrap{display:flex;gap:24px;padding:22px 16px 26px;background:none}
.drop{min-width:220px;background:#fff;border-top:3px solid var(--red);box-shadow:0 12px 26px rgba(0,0,0,.16);padding:6px 0}
.drop a{display:block;padding:9px 18px;font-size:14px;color:var(--ink)}
.drop a:hover{background:var(--soft);color:var(--red)}
.nav-list>li:hover>.mega,.nav-list>li:hover>.drop,.nav-list>li:focus-within>.mega,.nav-list>li:focus-within>.drop{opacity:1;visibility:visible;transform:none}
.nav-list>li.has-drop{position:relative}
.mega-sub{width:170px;flex:none;display:flex;flex-direction:column;gap:2px;border-right:1px solid rgba(255,255,255,.35);padding-right:14px}
.mega-sub a{padding:7px 0;font:700 15px var(--fh);color:#fff}
.mega-sub a:hover{color:var(--gold)}
.mega-main{flex:1;min-width:0}
.mega-main h4{display:flex;align-items:center;gap:8px;color:#fff;font:700 16px var(--fh);text-transform:uppercase;margin-bottom:14px}
.mega-main h4:before{content:'';width:4px;height:20px;background:var(--red)}
.mega-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;min-height:150px}
.mega-grid .th{border-radius:6px}
.mega-grid h3{font:700 15px/1.3 var(--fh);color:#fff;margin-top:10px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.mega-grid time{display:block;font-size:10px;color:#c9d3ea;margin-top:8px}
.mega-grid a:hover h3{color:var(--gold)}

/* ---------- Menu kedua ---------- */
.sec-nav{background:var(--sec)}
.sec-nav ul{display:flex;align-items:center;gap:24px;height:38px;overflow-x:auto;scrollbar-width:none}
.sec-nav ul::-webkit-scrollbar{display:none}
.sec-nav a{font:700 14.4px var(--fb);color:var(--navy);white-space:nowrap}
.sec-nav a:hover{color:var(--red)}
.pre{color:var(--red)}

/* ---------- Ticker HEADLINE ---------- */
.ticker{background:#fff}
.ticker .wrap{padding-top:8px;padding-bottom:8px}
.tk{display:flex;align-items:center;height:30px;background:#111;border-radius:6px;overflow:hidden}
.tk-label{flex:none;align-self:stretch;display:flex;align-items:center;background:var(--red);color:#fff;font:600 12px var(--fb);padding:0 18px 0 8px;position:relative;border-radius:6px 0 0 6px}
.tk-label:after{content:'';position:absolute;right:-1px;top:0;bottom:0;width:12px;background:#111;border-radius:14px 0 0 14px}
.tk-view{flex:1;overflow:hidden;min-width:0}
.tk-track{display:inline-flex;gap:30px;white-space:nowrap;animation:tick 80s linear infinite;padding-left:8px}
.tk-track:hover{animation-play-state:paused}
.tk-track a{color:#fff;font:600 12.8px var(--fb);display:inline-flex;align-items:center;gap:8px}
.tk-track a:hover{color:var(--gold)}
.tk-track svg{width:12px;height:12px;fill:#fff;flex:none}
@keyframes tick{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Iklan melayang kiri/kanan ---------- */
.sky{position:fixed;top:150px;width:160px;z-index:20;display:none}
.sky-l{left:calc(50% - 540px - 176px)}
.sky-r{right:calc(50% - 540px - 176px)}
@media (min-width:1440px){.sky{display:block}}

/* ---------- Layout ---------- */
.site-main{padding:22px 0 10px}
.layout{display:grid;grid-template-columns:minmax(0,1fr) var(--side);gap:var(--gap);align-items:stretch}
.content{min-width:0}
.sidebar{min-width:0;display:flex;flex-direction:column;gap:28px}
.sidebar>.section{display:flex;flex-direction:column;gap:28px}
.sidebar>.side-sticky{flex:1}
.sidebar>.side-sticky .widget{position:sticky;top:calc(var(--stick) + 10px)}
.blk{margin-bottom:34px}
.sk{background:linear-gradient(90deg,#f0f1f3 25%,#e6e8eb 37%,#f0f1f3 63%);background-size:400% 100%;animation:skl 1.4s ease infinite;border-radius:var(--r);height:260px}
@keyframes skl{0%{background-position:100% 50%}100%{background-position:0 50%}}

/* ---------- Judul section (bar merah) ---------- */
.sh{display:flex;align-items:flex-end;justify-content:space-between;gap:12px;margin-bottom:16px}
.sh-t{border-left:4px solid var(--red);padding:1px 0 1px 8px;min-width:0}
.sh-eb{display:block;font:400 9px/1.2 var(--fb);text-transform:uppercase;color:#333;margin-bottom:3px}
.sh h2,.sh h1{font:700 20px/1.2 var(--fh);color:var(--navy);text-transform:uppercase}
.sh h2 a:hover{color:var(--red)}
.more{flex:none;font-size:12px;color:#555;white-space:nowrap}
.more:before{content:'+ '}
.more:hover{color:var(--red)}
.sh-r{display:flex;align-items:center;gap:10px;flex:none}

/* ---------- Pill kategori & waktu ---------- */
.pill{display:inline-flex;align-items:center;background:var(--pill);color:var(--red-d);font:400 9px/1 var(--fb);text-transform:uppercase;padding:5px 10px 6px;border-radius:999px;white-space:nowrap}
.pill:hover{background:var(--red);color:#fff}
.meta{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:9px}
.ago{font-size:9.6px;color:#555}

/* ---------- Gambar ---------- */
.th{display:block;position:relative;overflow:hidden;border-radius:var(--r);background:#e7e8ea}
.th img{width:100%;height:100%;object-fit:cover;transition:transform .35s}
a:hover>.th img,a.th:hover img{transform:scale(1.04)}
.r169{aspect-ratio:16/9}.r1610{aspect-ratio:16/10}.r43{aspect-ratio:4/3}.r23{aspect-ratio:2/3}.r45{aspect-ratio:4/5}.r11{aspect-ratio:1/1}

/* ---------- Baris berita (Terkini) ---------- */
.row{display:flex;gap:18px;align-items:center;margin-bottom:22px}
.row>.th{width:234px;flex:none;aspect-ratio:16/9}
.row-b{min-width:0;flex:1}
.row-eb{display:block;font:700 11px var(--fb);color:var(--navy);text-transform:uppercase;margin-bottom:6px}
.row h3,.row h2{font:700 20px/24px var(--fh);color:var(--ink)}
.row h3 a:hover,.row h2 a:hover{color:var(--red)}
.row .snip{display:none}

/* ---------- Kartu ---------- */
.g3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.g4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.card h3{font:700 15px/1.3 var(--fh);margin-top:10px;color:var(--ink)}
.card h3 a:hover{color:var(--red)}
.card .meta{margin-top:8px}
.reg{display:block;font:400 9px var(--fb);color:var(--red-d);text-transform:uppercase;margin-top:10px}
.reg+h3{margin-top:4px}
.dotline{display:flex;align-items:center;gap:10px;margin-top:20px}
.dotline:before{content:'';flex:1;border-top:2px dotted #a3a3a3}
.sep-line{border:0;border-top:1px solid var(--line);margin:4px 0 24px}

/* ---------- Kartu overlay ---------- */
.ov{position:relative;display:block;border-radius:var(--r);overflow:hidden;color:#fff;background:#222}
.ov>.th{border-radius:0;height:100%}
.ov-b{position:absolute;left:0;right:0;bottom:0;padding:60px 16px 14px;background:linear-gradient(transparent,rgba(0,0,0,.86))}
.ov-b h3,.ov-b h2{font:700 18px/1.3 var(--fh)}
.ov-t{display:block;font-size:10px;opacity:.92;margin-bottom:5px}
.ov:hover h3,.ov:hover h2{text-decoration:underline}

/* ---------- Headline slider ---------- */
.hl-stage{position:relative;border-radius:var(--r) var(--r) 0 0;overflow:hidden;background:#d9d9d9}
.hl-track{display:flex;transition:transform .5s ease}
.hl-slide{flex:0 0 100%;min-width:0;position:relative;display:block;color:#fff}
.hl-slide>.th{aspect-ratio:16/9;border-radius:0}
.hl-cap{position:absolute;left:0;right:0;bottom:0;padding:100px 26px 50px;background:linear-gradient(transparent,rgba(0,0,0,.84))}
.hl-cap time{font-size:11px}
.hl-cap h2{font:700 28px/1.3 var(--fh);margin-top:6px}
.hl-slide:hover h2{text-decoration:underline}
.hl-dots{position:absolute;left:0;right:0;bottom:12px;display:flex;justify-content:center;gap:2px;z-index:2}
.hl-dots button{width:24px;height:24px;display:flex;align-items:center;justify-content:center}
.hl-dots button:before{content:'';width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,.5)}
.hl-dots button.on:before{background:#fff}
.hl-strip{background:var(--soft);border-radius:0 0 var(--r) var(--r);padding:32px 36px 22px;position:relative}
.hl-tag{position:absolute;left:16px;top:-16px;background:var(--navy);color:#fff;font:700 14px var(--fh);padding:7px 16px;border-radius:5px;text-transform:uppercase}
.hl-sv{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 24px)/2);gap:24px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;scroll-behavior:smooth}
.hl-sv::-webkit-scrollbar{display:none}
.hl-sv>div{scroll-snap-align:start;min-width:0}
.hl-sv h3{font:700 16px/1.3 var(--fh)}
.hl-sv h3 a:hover{color:var(--red)}
.hl-arr{position:absolute;top:50%;transform:translateY(-50%);width:22px;height:36px;background:#a9a9a9;color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px}
.hl-arr:hover{background:var(--red)}
.hl-prev{left:0;border-radius:0 18px 18px 0}.hl-next{right:0;border-radius:18px 0 0 18px}

/* ---------- Hot isu (carousel) ---------- */
.ci{width:34px;height:34px;border-radius:50%;border:1.5px solid var(--red);color:var(--red);display:flex;align-items:center;justify-content:center;background:#fff;flex:none}
.ci:hover{background:var(--red);color:#fff}
.ci svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.2}
.hs{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 32px)/3);gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;scroll-behavior:smooth}
.hs::-webkit-scrollbar{display:none}
.hs>*{scroll-snap-align:start;min-width:0}

/* ---------- Panel navy (sorotan) ---------- */
.panel{background:var(--navy);border-radius:10px;padding:18px 18px 22px;color:#fff}
.panel-h{display:flex;justify-content:space-between;align-items:center;gap:12px}
.panel-h h2{font:900 22px var(--fh);letter-spacing:.14em;text-transform:uppercase}
.panel-h h2 .pre{color:#ff5b62}
.panel-h .more{color:#fff;opacity:.9}
.panel-h .more:before{content:''}
.panel-d{font-size:15px;line-height:1.6;margin:16px 0 12px;opacity:.95}
.stripe{position:relative;height:16px;border-bottom:1px solid var(--red);margin-bottom:24px}
.stripe:after{content:'';position:absolute;right:0;bottom:2px;width:200px;height:12px;background:repeating-linear-gradient(90deg,var(--red) 0 12px,transparent 12px 18px)}
.panel .card .th{border-radius:10px}
.panel .card h3{color:#fff;text-align:center;font-size:16px;margin-top:12px}
.panel .card h3 a:hover{color:var(--gold)}

/* ---------- Video ---------- */
.vgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 16px}
.vmeta{display:flex;align-items:center;gap:9px;margin-top:10px;font-size:9.6px;color:#555}
.vmeta:before{content:'';border-left:11px solid var(--red);border-top:7px solid transparent;border-bottom:7px solid transparent}
.vplay{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:44px;height:44px;border-radius:50%;background:rgba(208,30,39,.92);display:flex;align-items:center;justify-content:center;opacity:0;transition:.2s}
.vplay:after{content:'';border-left:14px solid #fff;border-top:9px solid transparent;border-bottom:9px solid transparent;margin-left:4px}
a:hover .vplay{opacity:1}

/* ---------- Duo kanal & fokus ---------- */
.duo{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.duo .sh{margin-bottom:14px}
.duo .card h3{font-size:17px}
.mini{padding:12px 0;border-top:2px dotted #c2c2c2}
.mini:first-of-type{margin-top:14px}
.mini h3{font:700 15px/1.35 var(--fh)}
.mini h3 a:hover{color:var(--red)}
.mini .meta{margin-top:7px}
.fokus{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:16px}
.fokus>.ov>.th{aspect-ratio:4/3.3}
.fokus-s{display:grid;grid-template-rows:1fr 1fr;gap:16px;min-width:0}
.fokus-s .ov>.th{aspect-ratio:auto;height:100%;min-height:150px}
.fokus>.ov .ov-b h3{font-size:24px}
.fokus-s .ov-b{padding:40px 14px 12px}
.fokus-s .ov-b h3{font-size:15px}
.grid2{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:20px}
.grid2 .big h3{font:700 22px/1.3 var(--fh);margin-top:12px}
.list2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:24px}

/* ---------- Tombol muat lagi ---------- */
.btn-more{display:block;width:100%;background:var(--navy);color:#fff;text-align:center;padding:11px 12px;border-radius:6px;font:400 14px var(--fb);text-transform:uppercase;margin-top:4px}
.btn-more:hover{background:var(--red)}
.btn-more[disabled]{opacity:.6;cursor:wait}

/* ---------- Sidebar ---------- */
.st{display:flex;align-items:center;gap:8px;margin-bottom:16px;font:700 20px/1.2 var(--fh);color:var(--ink);text-transform:uppercase}
.st:after{content:'';flex:1;border-top:2px dotted #9a9a9a;margin-top:4px;min-width:20px}
.st svg{width:20px;height:20px;fill:var(--ink);flex:none}
.tags-c{display:flex;flex-wrap:wrap;gap:8px}
.tags-c a{background:var(--red);color:#fff;font:700 10px var(--fb);padding:7px 14px;border-radius:999px}
.tags-c a:hover{background:var(--navy)}
.pop li{display:flex;gap:14px;padding:14px 0;border-bottom:2px dotted #b5b5b5}
.pop li:first-child{padding-top:0}
.pop .n{flex:none;width:34px;text-align:center;font:700 32px/1 var(--fh);color:var(--navy);padding-top:6px}
.pop .pb{min-width:0}
.pop a.t{font:700 15px/1.3 var(--fh);color:var(--ink);display:block}
.pop a.t:hover{color:var(--red)}
.pop .pill{margin-top:8px}
.side-more{display:flex;align-items:center;gap:10px;margin-top:12px;font-size:12px;color:#555;white-space:nowrap}
.side-more:before{content:'';flex:1;border-top:2px dotted #9a9a9a}
.side-more:hover{color:var(--red)}
.foto{background:var(--navy);border-radius:var(--r);overflow:hidden;color:#fff}
.foto-h{text-align:center;padding:12px 10px;font:900 20px var(--fh);letter-spacing:.06em;text-transform:uppercase}
.foto-h span{display:inline-block;background:#fff;color:var(--navy);padding:0 6px;border-radius:3px;margin:0 3px}
.foto-stage{position:relative;overflow:hidden}
.foto-track{display:flex;transition:transform .45s ease}
.foto-sl{flex:0 0 100%;position:relative;display:block;min-width:0}
.foto-sl>.th{border-radius:0;aspect-ratio:4/3}
.foto-cap{position:absolute;left:0;right:0;bottom:0;padding:50px 14px 14px;background:linear-gradient(transparent,rgba(7,37,105,.96))}
.foto-cap h3{font:700 15px/1.3 var(--fh)}
.foto-n{display:flex;gap:6px;align-items:center;font-size:11px;opacity:.9;margin-bottom:4px}
.foto-arr{position:absolute;top:38%;width:30px;height:40px;color:#fff;font-size:24px;display:flex;align-items:center;justify-content:center;text-shadow:0 1px 3px rgba(0,0,0,.6)}
.foto-arr.l{left:2px}.foto-arr.r{right:2px}
.pbx{border:1px solid var(--navy);border-radius:var(--r);padding:16px 14px 6px}
.pbx-h{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:6px}
.pbx-h h4{font:900 18px var(--fh);color:var(--navy);text-transform:uppercase;letter-spacing:-.01em;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pbx-btn{flex:none;background:var(--navy);color:#fff;font:600 10px var(--fb);padding:5px 12px;border-radius:999px}
.pbx-i{display:flex;gap:12px;padding:12px 0;border-top:1px solid #ececec}
.pbx-i:first-of-type{border-top:0}
.pbx-i .tx{flex:1;min-width:0}
.pbx-i h3{font:700 15px/1.3 var(--fh);color:#1d58c4}
.pbx-i time{display:block;font-size:10px;color:#666;margin-top:6px}
.pbx-i>.th{width:72px;height:72px;flex:none;border-radius:6px}
.pbx.alt{border-color:#efa04a}.pbx.alt .pbx-h h4{color:#df6a14}.pbx.alt .pbx-btn{background:#ee9a3e}.pbx.alt h3{color:#d9620c}
.feat h3{font:700 16px/1.35 var(--fh);margin-top:12px}
.feat h3 a:hover{color:var(--red)}
.op{display:flex;gap:14px;align-items:center;background:var(--soft);border-radius:var(--r);padding:16px;margin-bottom:12px}
.op img{width:46px;height:46px;border-radius:50%;object-fit:cover;filter:grayscale(1);flex:none;border:2px solid #fff;box-shadow:0 0 0 1px #c9c9c9}
.op h3{font:700 15px/1.3 var(--fh)}
.op h3 a:hover{color:var(--red)}
.op small{display:block;font-size:12px;color:#666;margin-top:6px}
.sidebar .widget-content{font-size:14px}
.sidebar .widget ul li{padding:5px 0}

/* ---------- Halaman kanal / pencarian ---------- */
.ctab{display:flex;align-items:center;gap:20px;border-bottom:1px solid var(--line);margin-bottom:18px;overflow-x:auto;scrollbar-width:none}
.ctab::-webkit-scrollbar{display:none}
.ctab h1{font:700 14px var(--fh);color:var(--red);text-transform:uppercase;padding:10px 0 8px;border-bottom:3px solid var(--red);margin-bottom:-1px;white-space:nowrap}
.ctab .sep{color:#9a9a9a}
.ctab a{font-size:13.5px;color:#333;white-space:nowrap}
.ctab a:hover{color:var(--red)}
.cat-hero{margin-bottom:26px}
.cat-hero>.th{aspect-ratio:16/9}
.cat-hero .ov-b{padding:110px 24px 22px}
.cat-hero .ov-b h2{font-size:28px}
.empty{padding:40px 0;text-align:center;color:var(--muted)}

/* ---------- Artikel ---------- */
.crumb{display:flex;align-items:center;gap:8px;font-size:12px;color:#555;margin-bottom:14px;flex-wrap:wrap}
.crumb a.lb{color:var(--red);font-weight:700}
.crumb svg{width:10px;height:10px;fill:#555}
.a-title{font:700 36px/1.25 var(--fh);color:var(--navy);margin-bottom:12px}
.a-date{font-size:12px;color:#555}
.a-meta{display:flex;justify-content:space-between;align-items:center;gap:14px;margin:16px 0 18px;flex-wrap:wrap}
.a-by{display:flex;align-items:center;gap:10px;font-size:11.5px;color:#555;min-width:0}
.a-av{display:flex}
.a-av span{width:34px;height:34px;border-radius:50%;background:var(--navy);color:#fff;font:700 13px var(--fh);display:flex;align-items:center;justify-content:center;border:2px solid #fff}
.a-av span+span{margin-left:-8px;background:var(--red)}
.a-by b{color:var(--navy)}
.a-by .ed{color:var(--red);font-weight:700}
.share{display:flex;gap:8px;align-items:center}
.share a,.share button{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff}
.share svg{width:17px;height:17px;fill:currentColor}
.s-fb{background:#1877f2}.s-x{background:#111}.s-wa{background:#25d366}.s-tg{background:#2aa1da}.s-cp{background:#7b7b7b}
.share a:hover,.share button:hover{opacity:.85}
.a-body{font:400 16.8px/1.75 var(--fb);color:var(--ink)}
.a-body p,.a-body>div{margin-bottom:20px}
.a-body h2,.a-body h3,.a-body h4{font-family:var(--fh);color:var(--navy);margin:26px 0 12px;line-height:1.3}
.a-body h2{font-size:24px}.a-body h3{font-size:20px}
.a-body a{color:var(--navy-2);text-decoration:underline}
.a-body img{border-radius:var(--r);margin:0 auto}
.a-body .separator{margin-bottom:8px}
.a-body .separator a{display:block;margin:0!important}
.a-body .tr-caption-container{width:100%;margin-bottom:20px}
.a-body .tr-caption,.a-body figcaption{font:400 12px/1.5 var(--fb);color:#666;text-align:left!important;padding:8px 0 0}
.a-body blockquote{border-left:4px solid var(--red);background:var(--soft);padding:14px 18px;margin:20px 0;font-style:italic}
.a-body ul,.a-body ol{margin:0 0 20px 22px}
.a-body ul{list-style:disc}.a-body ol{list-style:decimal}
.a-body table{width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px}
.a-body td,.a-body th{border:1px solid var(--line);padding:8px}
.a-body iframe{max-width:100%}
.baca{background:var(--pill);border-radius:var(--r);padding:12px 16px;margin:0 0 22px;font-family:var(--fh)}
.baca b{display:block;font:400 14px var(--fh);color:var(--red-d);text-transform:uppercase;margin-bottom:4px}
.baca a{display:block;font:700 16px/1.35 var(--fh);color:var(--navy);text-decoration:none}
.baca a:hover{color:var(--red)}
.a-tags{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:8px 0 24px}
.a-tags span{font:700 13px var(--fh);color:var(--navy);margin-right:2px}
.a-tags a{font-size:12px;background:var(--soft);border:1px solid var(--line);padding:5px 12px;border-radius:999px}
.a-tags a:hover{background:var(--red);border-color:var(--red);color:#fff}
.follow{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:10px 0 34px}
.follow a{display:flex;align-items:center;gap:12px;border:1px solid #dcdcdc;border-radius:var(--r);padding:16px;font:700 13px var(--fb);color:var(--navy)}
.follow a:after{content:'+';margin-left:auto;font-size:20px;font-weight:400;color:#777}
.follow a:hover{border-color:var(--navy)}
.follow svg{width:24px;height:24px;flex:none}
.upd{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}
.upd>.ov>.th{aspect-ratio:16/10}
.upd .mini:first-of-type{margin-top:0;border-top:0;padding-top:0}
.cmts{margin:34px 0}
.cmt{padding:14px 0;border-bottom:1px solid var(--line);font-size:14px}
.cmt b{color:var(--navy)}
.cmt .ct{font-size:11px;color:#777;margin-left:6px}
.cmt p{margin-top:4px}

/* ---------- Footer (abu-abu) ---------- */
.site-footer{background:var(--foot);margin-top:30px;color:#555;font-size:12px}
.ft{display:grid;grid-template-columns:230px minmax(0,1.3fr) minmax(0,1fr) minmax(0,1.3fr);gap:28px;padding-top:26px;padding-bottom:18px}
.ft-split{columns:2;column-gap:16px}
.ft-split li{break-inside:avoid}
.is-home #list-more{display:none}
.ft-brand{text-align:center;display:flex;flex-direction:column;align-items:center}
.ft-brand .logo-text{font-size:19px}
.ft-brand img{max-height:36px;width:auto}
.ft-desc{font-size:11px;line-height:1.6;margin-top:10px}
.ft-k{font:700 10.5px var(--fb);color:#222;margin:12px 0 8px}
.soc{display:flex;justify-content:center;gap:6px;flex-wrap:wrap}
.soc a{width:28px;height:28px;border-radius:50%;background:#1d1d1f;display:flex;align-items:center;justify-content:center}
.soc a:hover{background:var(--red)}
.soc svg{width:15px;height:15px;fill:#fff}
.apps{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
.apps a{display:flex;align-items:center;gap:6px;background:#000;color:#fff;border-radius:5px;padding:4px 9px 5px;font:600 11px/1.1 var(--fb);text-align:left;border:1px solid #444}
.apps a small{display:block;font-size:7px;font-weight:400}
.apps svg{width:16px;height:16px;fill:#fff;flex:none}
.ft h4{font:700 10px var(--fb);color:#333;text-transform:uppercase;letter-spacing:.04em;margin-bottom:12px}
.ft li{padding:0 0 10px}
.ft a{color:#555}
.ft a:hover{color:var(--red)}
.ft-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));column-gap:16px}
.fbot{border-top:1px solid #c6c6c6;padding:14px 0 18px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;font-size:11px;color:#555}
.fbot b{display:inline-block;background:var(--navy);color:#fff;font:900 11px var(--fh);padding:4px 8px;border-radius:2px;margin-left:6px;letter-spacing:.03em}
.fbot b i{font-style:normal;background:var(--red);padding:0 4px;margin-right:4px;border-radius:2px}
.social-src{display:none}

/* ---------- Mobile: drawer, iklan sticky, ke atas ---------- */
.drawer{position:fixed;inset:0;z-index:200;visibility:hidden}
.drawer.open{visibility:visible}
.drawer-bg{position:absolute;inset:0;background:rgba(0,0,0,.5);opacity:0;transition:.2s}
.drawer.open .drawer-bg{opacity:1}
.drawer-p{position:absolute;top:0;left:0;bottom:0;width:300px;max-width:86%;background:#fff;transform:translateX(-100%);transition:.25s;overflow-y:auto}
.drawer.open .drawer-p{transform:none}
.drawer-h{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;background:var(--red);color:#fff;font:800 16px var(--fh)}
.drawer-h button{color:#fff;font-size:28px;line-height:1;width:36px;height:36px}
.drawer .hd-search{margin:14px;max-width:none;display:flex}
.m-nav li{border-bottom:1px solid var(--line)}
.m-nav a{display:block;padding:12px 16px;font-weight:700;color:var(--navy)}
.m-row{display:flex;align-items:center}
.m-row a{flex:1}
.m-tg{width:46px;height:46px;font-size:20px;color:#777}
.m-nav ul ul{display:none;background:var(--soft)}
.m-nav li.open>ul{display:block}
.m-nav ul ul a{padding-left:30px;font-weight:600;font-size:14px;color:var(--ink)}
.ad-mob{position:fixed;left:0;right:0;bottom:0;z-index:150;background:#fff;box-shadow:0 -2px 10px rgba(0,0,0,.15);display:none;padding:4px 0}
.ad-mob .ad-x{position:absolute;top:-24px;right:6px;width:26px;height:24px;background:#fff;border-radius:4px 4px 0 0;box-shadow:0 -2px 6px rgba(0,0,0,.12);font-size:16px;color:#555}
.totop{position:fixed;right:16px;bottom:84px;width:42px;height:42px;border-radius:50%;background:var(--navy);color:#fff;display:flex;align-items:center;justify-content:center;opacity:0;visibility:hidden;transition:.2s;z-index:140}
.totop.show{opacity:1;visibility:visible}

/* ---------- Responsif ---------- */
@media (max-width:1100px){
  .nav-list>li>a{padding:0 9px;font-size:13.5px}
  .hd-ico{padding:0 14px}
}
@media (max-width:991px){
  :root{--stick:104px}
  .hd{height:60px;gap:10px}
  .hd-btn{display:flex}
  .hd .logo{margin:0 auto}
  .hd-search,.hd-icons{display:none}
  .logo-text{font-size:21px}
  .main-nav{background:var(--red)}
  .nav-list{overflow-x:auto;scrollbar-width:none;justify-content:flex-start}
  .nav-list::-webkit-scrollbar{display:none}
  .mega,.drop{display:none!important}
  .nav-list>li.has-drop{position:static}
  .sec-nav ul{height:34px;gap:18px}
  .sec-nav a{font-size:13px}
  .layout{grid-template-columns:minmax(0,1fr)}
  .sidebar>.side-sticky .widget{position:static}
  .ft{grid-template-columns:repeat(2,minmax(0,1fr))}
  .ad-mob{display:block}
  body{padding-bottom:62px}
  .ph-970x250,.ph-970x90,.ph-728x90{width:320px;height:100px}
}
@media (max-width:767px){
  .site-main{padding-top:14px}
  .row{gap:12px;margin-bottom:16px;align-items:flex-start}
  .row>.th{width:130px;aspect-ratio:4/3}
  .row h3,.row h2{font-size:15px;line-height:1.35}
  .hl-cap{padding:60px 14px 40px}
  .hl-cap h2{font-size:19px}
  .hl-strip{padding:28px 30px 16px}
  .hl-sv{grid-auto-columns:100%}
  .hl-sv h3{font-size:15px}
  .g3,.panel .g3{grid-auto-flow:column;grid-template-columns:none;grid-auto-columns:62%;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;padding-bottom:4px}
  .g3::-webkit-scrollbar{display:none}
  .g3>*{scroll-snap-align:start}
  .g4,.vgrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 12px}
  .hs{grid-auto-columns:62%}
  .duo,.fokus,.grid2,.list2,.upd,.follow{grid-template-columns:minmax(0,1fr)}
  .fokus>.ov .ov-b h3{font-size:19px}
  .a-title{font-size:25px}
  .a-body{font-size:16px}
  .cat-hero .ov-b{padding:60px 14px 14px}
  .cat-hero .ov-b h2{font-size:19px}
  .card h3{font-size:14px}
}
@media (max-width:600px){
  .ft{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 16px}
  .ft-brand,.ft>:nth-child(2){grid-column:1/-1}
  .ft-split{columns:1}
  .vgrid{grid-template-columns:minmax(0,1fr)}
  .vgrid .card{display:flex;gap:12px;align-items:flex-start}
  .vgrid .card>.th{width:140px;flex:none}
  .vgrid .card h3{margin-top:0}
  .a-meta{flex-direction:column;align-items:flex-start}
  .fbot{justify-content:center;text-align:center}
}
@media (max-width:400px){
  .row>.th{width:112px}
  .logo-text{font-size:18px}
}
/* Aktivasi TemaBlogger: Cloudflare + cache bertanda tangan 24 jam. */
.tmb-license-section{display:none}
.tmb-gate{position:fixed;inset:0;z-index:2147483000;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(18,18,23,.72);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);font-family:var(--fb,'Open Sans',Arial,sans-serif);overflow-y:auto;overscroll-behavior:contain}
.tmb-gate[hidden]{display:none!important}
html.tmb-gate-on,html.tmb-gate-on body{overflow:hidden!important}
.tmb-gate-card{box-sizing:border-box;width:100%;max-width:550px;max-height:calc(100dvh - 48px);overflow-y:auto;background:#fff;color:#222;border-radius:20px;padding:35px 30px 29px;text-align:center;box-shadow:0 24px 65px rgba(0,0,0,.30);line-height:1.55}
.tmb-gate-icon{width:70px;height:70px;margin:0 auto 17px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:linear-gradient(105deg,#f02026,#452178);color:#fff}
.tmb-gate-icon svg{width:34px;height:34px;fill:currentColor}
.tmb-gate-card h2{margin:0 0 10px;font-family:var(--fh,'Lato',Arial,sans-serif);font-size:28px;line-height:1.3;font-weight:900}
.tmb-gate-card p{margin:0 0 22px;font-size:17px;line-height:1.65;color:#696969}
.tmb-gate-message{margin:0 0 16px;padding:10px 12px;border-radius:10px;background:#fff0f0;color:#a21d26;font-size:13px;overflow-wrap:anywhere}
.tmb-gate-message:empty{display:none}
.tmb-gate-actions{display:flex;flex-direction:column;gap:11px}
.tmb-gate-button{display:flex;align-items:center;justify-content:center;min-height:58px;border-radius:999px;padding:12px 16px;font-family:var(--fh,'Lato',Arial,sans-serif);font-size:19px;font-weight:900;line-height:1.3;text-decoration:none!important;box-sizing:border-box}
.tmb-gate-buy{background:linear-gradient(100deg,#f02026,#452178);color:#fff!important}
.tmb-gate-key{border:1px solid #d9d9d9;background:#fff;color:#222!important}
.tmb-gate-button:hover{filter:brightness(.96)}
.tmb-gate-retry{border:0;background:none;padding:8px;color:#452178;cursor:pointer;font:700 14px var(--fb,Arial,sans-serif)}
.tmb-gate-retry[hidden]{display:none!important}
.tmb-gate-button:focus-visible,.tmb-gate-foot a:focus-visible{outline:3px solid #48217b;outline-offset:4px}
.tmb-gate-steps{margin:19px 0 0;padding:16px 18px;border-radius:13px;background:#f6f6f6;text-align:left;font-size:14px;line-height:1.75;color:#555;list-style:decimal inside}
.tmb-gate-foot{margin-top:15px;font-size:13px;color:#777}
.tmb-gate-foot a{color:inherit;text-decoration:none}
.tmb-gate-noscript{margin:0 0 14px;color:#a21d26;font-size:13px}
body#layout .tmb-license-section{display:block!important}
body#layout .tmb-gate{display:none!important}
@media(max-width:600px){.tmb-gate{padding:16px}.tmb-gate-card{padding:26px 20px 23px;border-radius:18px;max-height:calc(100dvh - 32px)}.tmb-gate-icon{width:58px;height:58px}.tmb-gate-card h2{font-size:23px}.tmb-gate-card p{font-size:15px;margin-bottom:18px}.tmb-gate-button{font-size:16px;min-height:52px}.tmb-gate-steps{font-size:13px;padding:13px 14px}}
@media(max-height:600px){.tmb-gate-card{padding-top:23px;padding-bottom:22px}.tmb-gate-icon{width:48px;height:48px;margin-bottom:10px}}


.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


/* Native license input is invisible on the public site. */
.tb-license-settings{display:none!important}

head.b:template-skin:
/* TemaBlogger License Key: native Layout controls remain editable. */
body#layout .tb-license-settings{display:block!important;width:auto!important;clear:both!important;margin:0 0 16px!important;padding:12px!important;border:1px solid #d8e3f5!important;border-radius:12px!important;background:#f0f5ff!important}
body#layout .tb-license-settings .add_widget{display:none!important}

/* TemaBlogger: CSS khusus panel native Blogger, kompatibel parser legacy. */
body#layout { min-width:0!important; max-width:1120px!important; margin:0 auto!important; padding:16px!important; background:#eef2f6!important; color:#26364c!important; font:14px/1.5 Arial,sans-serif!important; text-align:left!important; }
body#layout .tbly-pass { display:contents!important; }
body#layout .tbly-pass:before,body#layout .tbly-pass:after { content:none!important; display:none!important; }
body#layout .tbly-ignore { display:none!important; }
body#layout .tbly-group { display:block!important; clear:both!important; float:none!important; position:relative!important; top:auto!important; bottom:auto!important; left:auto!important; right:auto!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:0 0 20px!important; padding:18px!important; overflow:visible!important; transform:none!important; border:1px solid #d4deeb!important; border-radius:8px!important; background:#f8fafc!important; color:#26364c!important; text-align:left!important; }
body#layout .tbly-group:before { display:block!important; position:static!important; clear:both!important; margin:0 0 16px!important; padding:0 0 10px!important; border-bottom:1px solid #dce4ef!important; font:700 16px/1.4 Arial,sans-serif!important; color:#d01e27!important; background:none!important; }
body#layout .tbly-group:after { display:block!important; position:static!important; clear:both!important; margin:0!important; padding:4px 0 0!important; font:12px/1.6 Arial,sans-serif!important; color:#60718a!important; background:none!important; }
body#layout div.section>h4 { margin:0 0 10px!important; padding:0!important; font:700 13px/1.5 Arial,sans-serif!important; color:#34455c!important; word-wrap:break-word!important; }
body#layout div.section .widget { float:none!important; width:auto!important; min-width:0!important; max-width:none!important; height:auto!important; min-height:0!important; margin:10px 0 0!important; }
body#layout div.section .widget-content { min-width:0!important; border-radius:6px!important; background:#fff!important; }
body#layout div.section .layout-title { color:#394b62!important; }
body#layout div.section .layout-widget-description { color:#6a7a90!important; }
body#layout div.section .editlink,body#layout div.section .layout-widget-state { visibility:visible!important; opacity:1!important; }
body#layout div.section .add_widget { display:none!important; }

